        left_child = 2 * node
        right_child = 2 * node + 1
        if idx <= mid:
            self._update(left_child, start, mid, idx, value)
        else:
            self._update(right_child, mid + 1, end, idx, value)
        self.tree[node] = self.tree[left_child] + self.tree[right_child]

    def _range_sum(self, node, start, end, left, right):
        if right < start or end < left:
            return 0
        if left <= start and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        left_child = 2 * node
        right_child = 2 * node + 1
        return self._range_sum(left_child, start, mid, left, right) + \
               self._range_sum(right_child, mid + 1, end, left, right)

    def update(self, i, value):
