        self.n = len(nums)
        self.data = nums.copy()
        self.tree_size = 1
        while self.tree_size < self.n:
            self.tree_size <<= 1
        self.bit = [0] * (2 * self.tree_size)
        for i, val in enumerate(self.data):
            self._add(i, val)

    def _add(self, index, delta):
        i = index + self.tree_size
        while i < len(self.bit):
            self.bit[i] += delta
            i >>= 1

    def update(self, i, value):
        delta = value - self.data[i]
        self.data[i] = value
        self._add(i, delta)

    def _prefix_sum(self, index):
        total = 0
        i = index + self.tree_size
        while i > 0:
            total += self.bit[i]
            i -= i & (-i)
        return total

    def range_sum(self, left, right):
        return self._prefix_sum(right) - (self._prefix_sum(left - 1) if left > 0 else 0)
