def search_last_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    # First, check if target exists at all using a modified binary search
    # or just do a full search since we need the last occurrence.
    # Since duplicates can straddle the rotation point, finding the pivot is tricky.
    # Let's first find if target exists, then find the last occurrence.

    # Approach: Find the minimum element's index to determine rotation, but with duplicates it's complex.
    # Alternative: Do a binary search for the last occurrence, handling the rotated + duplicates case.

    # Let's first determine if target is present using a standard rotated search (any occurrence).
    # Then, if present, find the last occurrence.

    # Actually, with duplicates, it's easier to just do a linear scan in O(n) if needed, but let's try O(log n) average.

    # Standard binary search for target in rotated array with duplicates:
    # At each step, compare mid with left and right to determine which half is sorted.

    def binary_search_first(arr, target):
        """Find the first occurrence of target in a potentially rotated sorted array with duplicates."""
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                # Move left to find earlier occurrence
                right = mid - 1
            elif arr[left] == arr[mid]:
                # Can't determine which side is sorted, so shrink
                left += 1
            elif arr[left] <= arr[mid]:
                # Left half is sorted
                if arr[left] <= target < arr[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if arr[mid] < target <= arr[right]:
                    left = mid + 1
                else:
                    right = mid - 1
        return -1

    def binary_search_last(arr, target):
        """Find the last occurrence of target in a potentially rotated sorted array with duplicates."""
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                # Move right to find later occurrence
                left = mid + 1
            elif arr[right] == arr[mid]:
                # Can't determine which side is sorted, so shrink
                right -= 1
            elif arr[mid] <= arr[right]:
                # Right half is sorted
                if arr[mid] < target <= arr[right]:
                    left = mid + 1
                else:
                    right = mid - 1
            else:
                # Left half is sorted
                if arr[left] <= target < arr[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
        return left - 1

    # First check if target exists
    if binary_search_first(nums, target) == -1:
        return -1

    # Find the last occurrence
    return binary_search_last(nums, target)
