import time


class RateLimiter:
    def __init__(self, rate, window, burst, clock, idle_ttl):
        self.rate = rate
        self.window = window
        self.burst = burst
        self.clock = clock
        self.idle_ttl = idle_ttl
        self._lock = threading.Lock()
        # key -> list of timestamps of permitted calls
        self._calls = {}
        # key -> last time any call (allowed or refused) was made
        self._last_seen = {}

    def _is_idle(self, key, now):
        if key not in self._last_seen:
            return False
        return (now - self._last_seen[key]) >= self.idle_ttl

    def _forget_idle(self, now):
        """Remove keys that have been idle for at least idle_ttl seconds."""
        to_remove = []
        for key in list(self._calls.keys()):
            if key not in self._last_seen:
                to_remove.append(key)
            elif (now - self._last_seen[key]) >= self.idle_ttl:
                to_remove.append(key)
        for key in to_remove:
            del self._calls[key]
            if key in self._last_seen:
                del self._last_seen[key]

    def allow(self, key):
        now = self.clock()
        with self._lock:
            # First, check if this key is idle and should be forgotten
            if self._is_idle(key, now):
                # Forget it and treat as fresh
                if key in self._calls:
                    del self._calls[key]
                if key in self._last_seen:
                    del self._last_seen[key]

            # Also clean up other idle keys
            self._forget_idle(now)

            # Update last seen for this key
            self._last_seen[key] = now

            # Check the rate window: fewer than `rate` calls with timestamp > now - window
            # Check the burst window: fewer than `burst` calls with timestamp > now - 1.0

            if key not in self._calls:
                self._calls[key] = []

            calls = self._calls[key]

            # Count calls in the rate window
            rate_cutoff = now - self.window
            rate_count = sum(1 for ts in calls if ts > rate_cutoff)

            # Count calls in the burst window
            burst_cutoff = now - 1.0
            burst_count = sum(1 for ts in calls if ts > burst_cutoff)

            if rate_count < self.rate and burst_count < self.burst:
                calls.append(now)
                return True
            else:
                return False

    def key_count(self):
        with self._lock:
            return len(self._calls)
