def parse_ini(text: str) -> dict:
    sections: dict[str, dict[str, str]] = {}
    current_section: dict[str, str] = None
    last_key: str | None = None

    lines = text.splitlines()

    for raw_line in lines:
        stripped = raw_line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Check for comment line
        if stripped[0] in (';', '#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1].strip()
            if section_name in sections:
                current_section = sections[section_name]
            else:
                current_section = {}
                sections[section_name] = current_section
            last_key = None
            continue

        # Determine the section; DEFAULT if not yet set
        if current_section is None:
            current_section = {}
            sections["DEFAULT"] = current_section

        # Find the first occurrence of '=' or ':'
        eq_pos = raw_line.find('=')
        col_pos = raw_line.find(':')

        candidates = []
        if eq_pos != -1:
            candidates.append(eq_pos)
        if col_pos != -1:
            candidates.append(col_pos)

        if candidates:
            sep_pos = min(candidates)
            key = raw_line[:sep_pos].strip().lower()
            value = raw_line[sep_pos + 1:].strip()

            current_section[key] = value
            last_key = key
        else:
            # Continuation line
            if last_key is not None and current_section is not None:
                current_section[last_key] += " " + stripped
            # If no previous key, ignore (should not happen per spec, but be safe)

    return sections
