class RangeSum:
    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * (2 * self.n)
        # Build the Fenwick tree (Binary Indexed Tree)
        # Using a BIT is generally faster in CPython than a Segment Tree
        # because it uses a flat list and simple bitwise operations.
        self.nums = nums
        self.bit = [0] * (self.n + 1)
        for i in range(self.n):
            self._add(i + 1, nums[i])

    def _add(self, idx, val):
        while idx <= self.n:
            self.bit[idx] += val
            idx += idx & (-idx)

    def update(self, i, value):
        delta = value - self.nums[i]
        self.nums[i] = value
        self._add(i + 1, delta)

    def _query(self, idx):
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & (-idx)
        return s

    def range_sum(self, left, right):
        return self._query(right + 1) - self._query(left)
