        # Determine the first occurrence of either separator
        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        if sep_idx != -1:
            # New key-value pair
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section_name not in result:
