def search_last_rotated(nums, target):
    if not nums:
        return -1

    def find_pivot(arr):
        left, right = 0, len(arr) - 1
        pivot = 0
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > arr[right]:
                left = mid + 1
            else:
                right = mid
        return left

    def binary_search_last(arr, left, right, target):
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                result = mid
                left = mid + 1  # search right half for last occurrence
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    pivot = find_pivot(nums)

    # If not rotated, search entire array
    if pivot == 0:
        return binary_search_last(nums, 0, len(nums) - 1, target)

    # Search both parts and take the last occurrence (higher index)
    # Part 1: nums[0..pivot-1], Part 2: nums[pivot..end]

    # Since we want the last occurrence overall, we should search the part that comes later in index space.
    # The rotated array consists of two sorted subarrays: [0..pivot-1] and [pivot..end].
    # The "last" occurrence in the original array could be in either subarray.
    # We need to find the max index among all occurrences.

    result = -1

    # Check if target could be in the first part [0, pivot-1]
    # This part is sorted, and its values are >= nums[pivot] is NOT necessarily true due to duplicates.
    # Actually, after rotation, nums[0..pivot-1] are the "larger" part and nums[pivot..end] are the "smaller" part,
    # but with duplicates it's tricky. Let's just do binary search in both sorted segments.

    # Segment 1: indices 0 to pivot-1 (sorted)
    if pivot > 0:
        r1 = binary_search_last(nums, 0, pivot - 1, target)
        if r1 != -1:
            result = r1

    # Segment 2: indices pivot to len(nums)-1 (sorted)
    r2 = binary_search_last(nums, pivot, len(nums) - 1, target)
    if r2 != -1:
        result = r2 if r2 > result else result

    return result
