import time


class RateLimiter:
    def __init__(self, rate, window, burst, clock, idle_ttl):
        self._rate = rate
        self._window = window
        self._burst = burst
        self._clock = clock
        self._idle_ttl = idle_ttl
        self._per_key = {}
        self._lock = threading.RLock()

    def allow(self, key):
        now = self._clock()
        with self._lock:
            self._cleanup(now)

            if key not in self._per_key:
                self._per_key[key] = {'timestamps': [], 'last_access': now}

            entry = self._per_key[key]
            entry['last_access'] = now
            timestamps = entry['timestamps']

            window_start = now - self._window
            burst_start = now - 1.0

            window_count = 0
            burst_count = 0

            for ts in timestamps:
                if ts > window_start:
                    window_count += 1
                if ts > burst_start:
                    burst_count += 1

            if window_count < self._rate and burst_count < self._burst:
                timestamps.append(now)
                return True
            return False

    def key_count(self):
        with self._lock:
            return len(self._per_key)

    def _cleanup(self, now):
        to_remove = []
        for key, entry in self._per_key.items():
            if now - entry['last_access'] >= self._idle_ttl:
                to_remove.append(key)
        for key in to_remove:
            del self._per_key[key]
