class RangeSum:
    def __init__(self, nums):
        self.n = len(nums)
        # Use a Binary Indexed Tree (Fenwick Tree) for O(log n) updates and queries
        self.tree = [0] * (self.n + 1)
        self.nums = [0] * self.n
        for i, val in enumerate(nums):
            self.update(i, val)

    def update(self, i, value):
        delta = value - self.nums[i]
        self.nums[i] = value
        # Update the Fenwick Tree
        idx = i + 1
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & (-idx)

    def _query(self, i):
        # Returns prefix sum from 0 to i (inclusive)
        s = 0
        idx = i + 1
        while idx > 0:
            s += self.tree[idx]
            idx -= idx & (-idx)
        return s

    def range_sum(self, left, right):
        # sum[left...right] = prefix_sum(right) - prefix_sum(left-1)
        return self._query(right) - self._query(left - 1)
