class RangeSum:
    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * (2 * self.n)
        # Build the Fenwick tree (Binary Indexed Tree)
        # We use 1-indexed internally
        for i in range(self.n):
            self.tree[i + 1] = nums[i]
        # Build the tree
        for i in range(1, self.n + 1):
            parent = i + (i & -i)
            if parent <= self.n:
                self.tree[parent] += self.tree[i]

    def _update(self, i, delta):
        """Update the tree at position i (1-indexed) by adding delta."""
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i

    def _prefix_sum(self, i):
        """Get prefix sum from 1 to i (1-indexed)."""
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

    def update(self, i, value):
        """Set nums[i] to value."""
        # We need the current value to compute delta
        # Get current value via prefix_sum(i+1) - prefix_sum(i)
        current = self._prefix_sum(i + 1) - self._prefix_sum(i)
        delta = value - current
        self._update(i + 1, delta)

    def range_sum(self, left, right):
        """Return sum of nums[left] through nums[right], inclusive."""
        return self._prefix_sum(right + 1) - self._prefix_sum(left)
